style.css.after:
.bulk-app #dayView:not(.routine-editing) #dayPanel .weight-source-note{margin-block:2px}

/* v167 exercise-only toolbar and suggestion-source presentation. */
.bulk-app #dayView.routine-editing .exercise-edit-tools{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:6px 10px;align-items:start;margin:4px 0}
.bulk-app #dayView .exercise-edit-tools .ai-menu-trigger{margin:0;min-height:44px}
.bulk-app #dayView.routine-editing .exercise-edit-tools .routine-advanced-options{margin:0;min-width:0}
.bulk-app #dayView .exercise-edit-tools .routine-advanced-options>summary{min-height:44px;padding:0 8px;white-space:nowrap}
.bulk-app #dayView .exercise-edit-tools:has(.routine-advanced-options[open]){grid-template-columns:1fr}
.bulk-app #dayView #dayPanel .record-compare-hint .weight-source-note{display:inline;margin:0 0 0 8px;font-size:12px;line-height:1.4}
.bulk-app #dayView #dayPanel .saved-set-summary .weight-source-note{display:inline;margin:0 8px 0 0;font-size:12px}
.bulk-app #dayView #dayPanel .saved-set-summary:has(.weight-source-note)>div{display:inline}
.bulk-app #dayView #dayPanel .weight-source-note[hidden]{display:none}
